import {imageSources,lazyImage} from './image-source.js';
export const gameImages=imageSources({"1-0":"data:image/svg+xml;base64,","1-1":"data:image/svg+xml;base64,","2-0":"data:image/svg+xml;base64,","2-1":"data:image/svg+xml;base64,","3-0":"data:image/svg+xml;base64,","3-1":"data:image/svg+xml;base64,","4-0":"data:image/svg+xml;base64,","4-1":"data:image/svg+xml;base64,","5-0":"data:image/svg+xml;base64,","5-1":"data:image/svg+xml;base64,","6-0":"data:image/svg+xml;base64,","6-1":"data:image/svg+xml;base64,","7-0":"data:image/svg+xml;base64,","7-1":"data:image/svg+xml;base64,","8-0":"data:image/svg+xml;base64,","8-1":"data:image/svg+xml;base64,","9-0":"data:image/svg+xml;base64,","9-1":"data:image/svg+xml;base64,","10-0":"data:image/svg+xml;base64,","10-1":"data:image/svg+xml;base64,","chip-5":"data:image/svg+xml;base64,","chip-10":"data:image/svg+xml;base64,","chip-20":"data:image/svg+xml;base64,","chip-50":"data:image/svg+xml;base64,","chip-100":"data:image/svg+xml;base64,","chip-1":"data:image/svg+xml;base64,"});
export function chipImage(value,cls=""){return `<img class="chip-image ${cls}" src="${gameImages["chip-"+value]||gameImages["chip-10"]}" alt="${value} 칩" width="60" height="60">`}
export function chipPile(amount){return `<span class="chip-pile" aria-label="${amount}칩">${[50,20,10,5].filter(v=>amount>=v).slice(0,3).map(v=>chipImage(v)).join("")}<b>${amount}</b></span>`}
export const ladderBoardImage=lazyImage('data:image/svg+xml;base64,');
